#!/usr/bin/env python3
"""Record reproducible scope counts; do not estimate overall completion from code counts."""
import csv,json
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
procedures=json.loads((ROOT/'analysis/rea/procedures.json').read_text())['result']['structuredContent']['normalized_result']
internal=[p for p in procedures if not p['procedure']['external'] and not p['procedure']['thunk']]
bindings=json.loads((ROOT/'analysis/rea/seed-bindings.json').read_text())
recovered_fields=len(bindings['bindings'])+len(bindings.get('integer_bindings',[]))
columns=next(csv.reader((ROOT/'analysis/data/ListData/ICThermoData.csv').open()))[2:]
model_bindings=json.loads((ROOT/'analysis/rea/model-bindings.json').read_text())
model_recovered=len(model_bindings['bindings'])
model_columns=next(csv.reader((ROOT/'analysis/data/ListData/BasicData.csv').open()))[2:]
known_math=['0x52cbc0','0x49a4f0','0x49a830','0x49ab70','0x49ae10','0x49b140','0x49b430','0x49bde0','0x49beb0','0x49be30','0x49bf00','0x49c190','0x49c1e0','0x49b3a0','0x49a3f0','0x5124e0','0x501e60']
partial={'0x526200':'continuous numerical Double/array initializer 0x52624b-0x5269d2 checked in 240 cases; 33 Double writes, 12 arrays and fresh temperature stores; COM/UI tail and evolution remain separate','0x50da40':'charging/letdown/injection numeric and control decisions checked in 960 original-slice cases; explicit stateful COM inputs, setter callbacks/log formatting/error dispatch excluded','0x500950':'spray selector numeric paths checked with original caller interlocks/manual-auto commands and flow in 640 cases; UI/error reporting excluded','0x500bd0':'heater numeric automatic/manual paths and low-level shutdown checked in 800 original-slice cases; explicit COM inputs, UI/error reporting excluded','0x51c310':'20 Single startup constants and one I16 checked against original scalar stores; external Double/property-array initialization incomplete','0x505370':'entire numeric loop-transfer body checked with original DLL power; normal driving and both caller bindings connected before SG/integration in 128 additional composed cases; shared event-8 time and A-to-B reference copy; Windows/UI/error context incomplete','0x51afe0':'pressurizer initial fractions/mass, loop startup heat, 15 reference globals and fresh pressure-reference/level-interlock initialization checked; fresh primary state/flags and connected inventory checked in 240+240 cases; GUI/CLI startup backend checked for all 110 model/operating-point pairs; fresh SG level/phase and feedwater initialization checked (320+300), connected thermal startup extended through 25 cached-state stores for all 110 model/operating-point pairs (79 Singles, 11 flags), plus 320 standalone fresh cached-state cases; late numeric reference/property slices checked in 320 cases and all 110 source pairs; early driving coefficient and unit factor now included (130 Singles, 15 flags; primitive constants and geometry included); 11 fresh control-history stores checked in 320 cases with explicit fault flag; restored control/time-reference branch and 20-event rebasing checked in 400 native cases; known event inputs connected in 32 more updates; Double/array numerical initializer now connected in assembled fresh-state output for all 110 source pairs, plus original floor-to-I16 clock; external model evolution, full restored loader/dispatch and complete initializer pending','0x510850':'supply-tank depletion checked in 200 cases; full recovered supply/injection/recirculation/cooling body checked in 960 continuous cases and connected in 96 updates; stateful controls retained across 12 eight-update chains; callbacks/logging/other source dispatch incomplete','0x50f660':'relief numeric discharge and caller bindings checked in 300 + 300 cases; post-discharge state/log-branch selection checked in 240 cases; valve automation and full protection/event dispatch incomplete','0x508960':'steam-generator final exchange, outflow limit and six derivative outputs checked; initial level/pressure/timed/fault control prefix checked in 960 cases and connected in 32 additional coordinator updates; shared timestamp, checkbox and fresh HGAS outputs preserved; device/valve/fault decisions and inventory-limited outflow producer checked in 1200 native cases plus 32 composed updates; auxiliary feedwater checked in 640 cases; complete recovered numerical/control body checked by 320 continuous native executions and 32 more composed updates; real COM callbacks/logging/error handling and plant dispatch remain excluded','0x512290':'bounded PI numeric update checked in 300 cases; UI/error reporting excluded','0x511b00':'discharge checked in 200 cases and activation/latch/valve decisions in 240 cases; continuous activation/discharge with original caller bindings checked in 640 more cases and connected to source sum/balance/integration in 64 composed updates; explicit valve COM properties, callbacks/logging and plant dispatch excluded','0x5011b0':'numeric vessel solver checked; native UI/error reporting not ported','0x512520':'RCP switching/timestamps/targets and flow sequence checked in 768 original-slice cases, plus 32 connected coordinator updates; explicit UI properties, scheduler, callbacks/logging/errors outside scope','0x51d3d0':'14-state integration, primary properties and normal/external thermal branches, properties and recovered-stage composition checked; shared-state 14-state integration/event update checked against 36 original coordinator slices; source/flux preparation, relief/primary/SG/stream/integration updates connected with explicit remaining boundaries; process-birth image storage checked separately; stream derivative bindings connected; complete step coordinator incomplete','0x50af30':'connected primary numeric core checked in 160 original-frame cases, including heat capacity, phase state/flow, four flag branches and final derivatives; heater numeric control connected with 160 additional composed-slice cases; spray numerical/control paths connected with 160 composed cases; post-balance exchange/level/temperature feedback checked in 320 cases and connected pressure/control/balance/feedback cycle in 160 cases; late hot/cold loop-temperature feedback and four histories checked in 640 continuous native cases and 16 eight-update chains; complete upstream initialization and UI event dispatch remain incomplete','0x4afbc0':'IC field loading partly ported','0x4c7340':'all 135 BasicData field conversions checked; post-load derived globals and initialization incomplete'}
records=[]
for p in internal:
    address=p['address'];status='numeric_helper_checked' if address in known_math else 'partial' if address in partial else 'evidence_only' if address=='0x51afe0' else 'unconverted'
    records.append({'address':address,'original_name':p['value'],'status':status,'note':partial.get(address,'Valid numeric helper semantics only; original VB error paths outside scope' if status=='numeric_helper_checked' else '')})
counts=Counter(r['status'] for r in records)
output_ports=json.loads((ROOT/'analysis/derivative_output_ports.json').read_text())['entries']
expected_outputs={hex(state['new_derivative_va']) for state in json.loads((ROOT/'analysis/integration_states.json').read_text())['states']}
assert len({entry['derivative_va'] for entry in output_ports})==len(output_ports)
assert all(entry['derivative_va'] in expected_outputs for entry in output_ports)
checked_outputs=sum(entry['checked'] for entry in output_ports)
output_total=len(expected_outputs)
scopes=[{'name':'Primary phase-flag branch numerical bodies','complete':4,'total':4,'remaining':0,'unit':'four zero/one flag combinations; not full plant dispatch'}, {'name':'Primary core connected derivative outputs','complete':5,'total':5,'remaining':0,'unit':'outputs with explicit cached upstream properties, command and heater heat'}, {'name':'IC thermodynamic field loading','complete':recovered_fields,'total':len(columns),'remaining':len(columns)-recovered_fields,'unit':'source fields'}, {'name':'Basic model field loading','complete':model_recovered,'total':len(model_columns),'remaining':len(model_columns)-model_recovered,'unit':'source fields'}, {'name':'Main integration stage','complete':14,'total':14,'remaining':0,'unit':'state updates, not derivative models'}, {'name':'Main derivative output equations','complete':checked_outputs,'total':output_total,'remaining':output_total-checked_outputs,'unit':'output equations; preceding component inputs still incomplete'}, {'name':'Complete end-to-end requested features','complete':0,'total':4,'remaining':4,'unit':'full simulation, operating controls, faults/protection, full histories/reports'}]
scopes=[scope for scope in scopes if scope['name']!='Complete end-to-end requested features']
result={'updated_date':'2026-10-21','overall_completion_percent':None,'overall_reason':'Complete original behavior inventory is not established; procedure counts and field counts do not measure project completion.','original_native_non_thunk_procedures':len(internal),'numeric_helpers_checked':counts['numeric_helper_checked'],'partial_procedures':counts['partial'],'evidence_only_procedures':counts['evidence_only'],'other_unconverted_procedures':counts['unconverted'],'scopes':scopes,'pending_ic_fields':bindings['pending'],'pending_model_fields':model_bindings['pending'],'procedures':records}
milestones=json.loads((ROOT/'analysis/CONVERSION_MILESTONES.json').read_text())
validation=json.loads((ROOT/'analysis/latest-validation.json').read_text())
result['milestones']=milestones['milestones']
result['changes']=milestones['changes']
result['progress_revision']=len(milestones['changes'])
result['scope_discoveries']=milestones['scope_discoveries']
result['remaining_work_estimate']=milestones['estimate']
result['validated_build']={k:validation[k] for k in ['component_cases_passed','component_output_checks_passed','rust_tests_passed','original_application_end_to_end']}
(ROOT/'analysis/conversion_progress.json').write_text(json.dumps(result,indent=2)+'\n')
lines=['# Postęp konwersji RustTran','','Aktualizacja: 21 października 2026.','','**Program nie jest jeszcze pełnym zamiennikiem PCTran. Pozostała znaczna praca.** Nie podajemy procentu całości ani liczby godzin bez zamkniętej listy zachowań i zależności oryginału. Wysokie pokrycie pól danych i liczba testów nie oznaczają gotowości aplikacji.','','## Co działa i czego użytkownik jeszcze nie może zrobić','','Widok **Simulation** wykonuje rzeczywiste kroki odzyskanego silnika: Start/Pause/Step/Reset, sterowanie urządzeniami, wykresy, zapis/odczyt sesji i eksport CSV. Wbudowany syntetyczny przykład uruchamia się przyciskiem **Load sample session**; można też dostarczyć JSON sesji. Kliknięcia i zgodność stanu GUI/CLI sprawdzono automatycznie. Panel inicjalizacji zachowuje także Double i tablice oraz zapisuje złożony stan JSON. Okno Live simulation mimic pokazuje bieżące odzyskane odczyty w układzie oryginalnego schematu; brakujące źródła mają znak —. Widoki IC nadal pokazują zapisane warunki i podgląd zegara. **Pełny start reaktora z IC i zgodność całych scenariuszy PCTran pozostają nieukończone.**','','## Stałe etapy do pełnej funkcjonalności','','Poniższe identyfikatory są stałe. Kolejne odkryte podproblemy zapisujemy pod właściwym etapem. Siedem pozycji nie oznacza siedmiu równych ani pojedynczych zadań.','','| ID | Etap | Stan | Co konkretnie pozostało |','|---|---|---|---|']
for m in milestones['milestones']:
    status={'partial':'Częściowo wykonany','not_validated':'Całe przebiegi niesprawdzone'}[m['status']]
    lines.append(f"| {m['id']} | {m['name']} | {status} | {m['remaining']} |")
lines+=['','## Co faktycznie ubyło w ostatnich zmianach','']
for c in reversed(milestones['changes']):
    lines.append(f"- **{c['id']}** ({', '.join(c['milestones'])}): {c['description']} Status: {c['status']}. [Dowód]({c['evidence']}).")
lines+=['','## Ostatni zweryfikowany zestaw','',f"- Przypadki komponentów i połączonych fragmentów: **{validation['component_cases_passed']}**.",f"- Sprawdzenia wyjść: **{validation['component_output_checks_passed']}**.",f"- Testy Rust: **{validation['rust_tests_passed']}**.",' - Całe scenariusze oryginalnej aplikacji Windows kontra RustTran: **jeszcze niezweryfikowane**.'.lstrip(),'','[Kolorowa tabela porównań](component-comparison/results.html) · [Szczegóły ostatniej walidacji](latest-validation.json).','','## Pokrycie wybranych fragmentów — osobno od gotowości programu','','| Zakres | Sprawdzone | Pozostało w tym zakresie |','|---|---:|---:|']
for scope in scopes:
    if scope['name']!='Complete end-to-end requested features':lines.append(f"| {scope['name']} | {scope['complete']}/{scope['total']} | {scope['remaining']} |")
lines+=['','Pozostałe pola IC: '+', '.join(x['field'] for x in bindings['pending'])+'. Wszystkie 135 pól modelu ma konwersję, ale pełna inicjalizacja po wczytaniu nadal wymaga pracy.','','## Dlaczego wcześniej lista wyglądała na rosnącą','','Poprzednie wpisy łączyły zakończone porty liczbowe, integrację i gotowe funkcje użytkowe. Określenie „pozostało połączenie układów” było zbyt ogólne: obejmowało też nieodtworzone sterowanie i inicjalizację. Kolejne analizy odsłaniają szczegóły tych zależności; mogą też ujawnić rzeczywiście dodatkowy zakres. Nowe, niezależne wymagania będą zapisane w scope_discoveries, zamiast po cichu zmieniać mianownik postępu.','','Inwentarz procedur jest zachowany w JSON do audytu, ale nie jest licznikiem zadań ani procentem ukończenia: obejmuje także obsługę starego GUI i VB6.','','Pełne kryteria odbioru i rejestr zmian: [CONVERSION_MILESTONES.json](CONVERSION_MILESTONES.json). Wcześniejsze szczegółowe notatki: [CONVERSION_HISTORY.md](CONVERSION_HISTORY.md). Kolejność zależności technicznych: [NEXT_ENGINE_WORK.md](NEXT_ENGINE_WORK.md).','','Aktualizacja obu plików postępu: `python3 scripts/update_conversion_progress.py`.']
(ROOT/'analysis/CONVERSION_PROGRESS.md').write_text('\n'.join(lines)+'\n')
print(f"IC: {recovered_fields}/{len(columns)}, remaining {len(columns)-recovered_fields}. Stable milestones: {len(milestones['milestones'])}. Native inventory: {dict(counts)}")
